def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    if n == 0:
        return '0\n'
    arr = list(map(int, lines[1].split()))

    if n == 0 or (len(set(arr)) == 1 and arr[0] == 0):
        # All zeros or empty sequence is GP
        if not arr:
            return '0\n'
        return '0\n'

    def is_gp(seq):
        k = len(seq)
        if k <= 2:
            return True
        if all(x == 0 for x in seq):
            return True

        # Check if we have zeros mixed with non-zeros
        zero_pos = [i for i, x in enumerate(seq) if x == 0]
        non_zero_pos = [i for i, x in enumerate(seq) if x != 0]

        if zero_pos and non_zero_pos:
            # If there are both zeros and non-zeros
            # Find if zeros occur only in a consistent pattern
            if zero_pos[0] < non_zero_pos[0] or (len(zero_pos) > 1 and zero_pos[1] < non_zero_pos[0]):
                # Zeros appear before first non-zero and then pattern continues
                # Check if the progression is all zeros
                if zero_pos[-1] != non_zero_pos[0] - 1:
                    return False
                # If zeros are at the beginning only
                remaining = seq[zero_pos[-1] + 1:]
                if remaining == []:
                    return True
                # Check if remaining forms a valid GP starting from non-zero
                # Actually, for a GP with ratio 0, we'd have zeros then non-zeros - but that's invalid
                # For ratio != 0, once non-zero appears, must stay non-zero unless next is also 0
                # [0, 0, ..., 0, non_zero, ...] is only valid if all after 0 are 0
                return False

        # Now we have either all zeros or all non-zeros
        if all(x == 0):
            return True

        # Check if first two elements determine a valid ratio
        # For a GP, seq[2] * seq[0] == seq[1] * seq[1] => seq[2]/seq[1] == seq[1]/seq[0]
        # Using cross multiplication: seq[i] * seq[i-2] == seq[i-1] * seq[i-1]

        for i in range(2, k):
            if seq[i] * seq[i-2] != seq[i-1] * seq[i-1]:
                return False
        return True

    if is_gp(arr):
        return '0\n'

    # Try removing each element
    if n == 1:
        return '1\n'  # Single element becomes empty after deletion, which is GP

    for i in range(n):
        test_arr = arr[:i] + arr[i+1:]
        if is_gp(test_arr):
            return '1\n'

    return '2\n'

