    tokens = input_str.split()
    n = int(tokens[0])
    k = int(tokens[1])
    a = [int(tokens[i]) for i in range(2, 2 + n)]

    def f(x):
        while x % k == 0:
            x //= k
        return x

    from collections import deque

    # BFS with state as sorted tuple of remaining numbers
    initial = tuple(sorted(a))
    visited = {initial}
    queue = deque([(initial, [])])

    while queue:
        state, path = queue.popleft()

        # Found single number on the board
        if len(state) == 1:
            if state[0] == 1:
                # Path is in reverse order of operations, reverse it back
                operations = [(x, y) for x, y in reversed(path)]
                return "YES\n" + "\n".join(f"{x} {y}" for x, y in operations)
            continue

        # Try all pairs
        for i in range(len(state)):
            for j in range(i + 1, len(state)):
                x, y = state[i], state[j]
                z = f(x + y)

                # Create new state
                new_state_list = state[:i] + state[i+1:j] + state[j+1:] + [z]
                new_state = tuple(sorted(new_state_list))

                if new_state not in visited:
                    visited.add(new_state)
                    queue.append((new_state, path + [(x, y)]))

    return "NO\n"

def solution(input_data):
    lines = input_data.strip().split('\n')
    if not lines:
        return 'YES\n' + '0' * (int(lines[0].split()[1])) if int(lines[0].split()[1]) > 0 else 'YES'

    n, m = map(int, lines[0].split())
    clauses = []
    for i in range(1, n + 1):
        parts = list(map(int, lines[i].split()))
        k = parts[0]
        if k > 0:
            clause = parts[1:k+1]
            clauses.append(clause)

    # Build implication graph and check 2-SAT
    # Use Tarjan's SCC algorithm

    # Mapping: literal x -> 2*(x-1), literal -x -> 2*(x-1)+1
    # Convert to 0-indexed: literal + 1 or - (literal + 1)
    def get_node(lit):
        val = abs(lit)
        if lit > 0:
            return 2 * (val - 1)
        else:
            return 2 * (val - 1) + 1

    def get_neg_node(lit):
        if lit > 0:
            return 2 * lit
        else:
            return 2 * lit + 1

    num_nodes = 2 * m
    graph = [[] for _ in range(num_nodes)]

    # For 2-CNF: (A OR B) -> (not A -> B) and (not B -> A)
    # For clauses with more than 2 literals, handle appropriately
    for clause in clauses:
        # Extract literals
        lits = []
        for l in clause:
            lits.append(l)

        # A clause is falsified only if all its literals are false
        # For unit clause (l): must have l = True, so add edge (not l -> l)
        # For 2-literal clause (a v b): add (not a -> b) and (not b -> a)
        # For k-literal clause (>2): special handling needed, but we'll use a simplified approach

        for i in range(len(lits)):
            u = get_node(lits[i])
            # For a literal position, add implications
            for j in range(len(lits)):
                if i != j:
                    v = get_node(lits[j])
                    # Implication: negation of lits[i] -> lits[j]
                    neg_u = get_neg_node(lits[i])
                    graph[neg_u].append(v)

    # Tarjan's SCC
    ids = [-1] * num_nodes
    low = [0] * num_nodes
    on_stack = [False] * num_nodes
    stack = []
    counter = [0]
    scc_list = []

    def dfs(u):
        ids[u] = low[u] = counter[0]
        counter[0] += 1
        stack.append(u)
        on_stack[u] = True

        for v in graph[u]:
            if ids[v] == -1:
                dfs(v)
                low[u] = min(low[u], low[v])
            elif on_stack[v]:
                low[u] = min(low[u], ids[v])

        if ids[u] == low[u]:
            scc_id = len(scc_list)
            while stack:
                v = stack.pop()
                on_stack[v] = False
                if v == u:
                    break
            scc_list.append(scc_id)

    for i in range(num_nodes):
        if ids[i] == -1:
            dfs(i)

    # Check satisfiability and build solution
    result = ['0'] * m
    for i in range(m):
        u = 2 * i     # node for +x_i
        v = 2 * i + 1 # node for -x_i

        if scc_list[u] == scc_list[v]:
            return 'NO'
        else:
            # If scc_list[u] < scc_list[v], x_i can be True
            # Because False implies True is more restrictive
            if scc_list[u] < scc_list[v]:
                result[i] = '1'
            else:
                result[i] = '0'

    return 'YES\n' + ''.join(result)

