def solution(s):
    s = s.strip()
    if not s:
        return '0'

    lines = s.split('\n')
    if not lines:
        return '0'

    n, m = map(int, lines[0].split())

    # Parse events into segments
    segments = []
    current = []

    for i in range(1, len(lines)):
        line = lines[i].strip()
        if not line:
            continue
        parts = line.split(maxsplit=1)
        if parts[0] == '1':
            segments.append(tuple(current))
            current = []
        else:
            # Format: "2 friend_name"
            current.append(parts[1] if len(parts) > 1 else '')

    # Don't forget the last segment
    if current:
        segments.append(tuple(current))

    # Map friend names to indices 0..k-1
    idx_map = {}
    k = 0
    for seg in segments:
        for f in seg:
            if f and f not in idx_map:
                idx_map[f] = k
                k += 1

    # Build conflict graph
    # conflict[i][j] = True if friends i and j share a segment
    conflict = [[False] * k for _ in range(k)]

    for seg in segments:
        friends_in_seg = []
        for f in seg:
            if f in idx_map:
                friends_in_seg.append(idx_map[f])
        # All pairs in the same segment conflict
        for i in range(len(friends_in_seg)):
            for j in range(i+1, len(friends_in_seg)):
                u, v = friends_in_seg[i], friends_in_seg[j]
                conflict[u][v] = True
                conflict[v][u] = True

    # Find Maximum Independent Set using DFS with pruning
    best = 0

    def dfs(idx, count, mask):
        nonlocal best

        # Update best found so far
        if count > best:
            best = count

        # Pruning: if not enough nodes left to beat best
        if idx == k:
            return
        if count + (k - idx) <= best:
            return

        # Try including idx
        can_include = True
        for neighbor in range(k):
            if conflict[idx][neighbor] and (mask & (1 << neighbor)):
                can_include = False
                break

        if can_include:
            dfs(idx + 1, count + 1, mask | (1 << idx))

        # Try excluding idx
        dfs(idx + 1, count, mask)

    dfs(0, 0, 0)
    return str(best)


