def check_progression_3(l, r):
    """Count geometric progressions of length 3 in range [l, r]"""
    count = 0

    for a in range(l, r + 1):
        # Try integer ratios d >= 2
        max_d = int(r / a)
        if max_d >= 2:
            for d in range(2, max_d + 1):
                a2 = a * d
                a3 = a2 * d
                if l <= a3 <= r:
                    count += 1

        # Try rational ratios d = p/q where p/q in lowest terms
        # This means a2 = a*p/q is integer => q divides a
        # Then a3 = a*p^2/q^2 must be integer => q^2 divides a*p^2

