def gpp_valid(p, q, a, l, r):
    """Check if p/q yields valid progression with starting term a"""
    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x

    g = gcd(p, q)
    p //= g
    q //= g

    if q == 1:  # Already integer
        return False

    # a2 = a*p/q must be integer
    if a % q != 0:
        return False

    a2 = (a * p) // q
    if not (l <= a2 <= r):
        return False

    # a3 = a*d^2 = a*p^2/q^2 must be integer
    if a * p * p % q * q != 0:
        return False

    a3 = (a * p * p) // (q * q)

    # All distinct
    if a == a2 or a2 == a3 or a == a3:
        return False

    if l <= a3 <= r:
        return True

    return False


def p_yields_valid(p, q, a, l, r):
    """Check if p/q yields valid progression with starting term a"""
    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x

    g = gcd(p, q)
    p //= g
    q //= g

    if q == 1:
        return False

    # Ensure p > q for expanding progression
    if p <= q:
        return False

    # a2 = a*p/q must be integer
    if a % q != 0:
        return False

    a2 = (a * p) // q
    if not (l <= a2 <= r):
        return False

    # a3 = a*p^2/q^2 must be integer
    if a * p * p % q * q != 0:
        return False

    a3 = (a * p * p) // (q * q)

    if not (l <= a3 <= r):
        return False

    # All distinct
    if a == a2 or a2 == a3 or a == a3:
        return False

    return True


def check_progression_4_plus(n, l, r):
