                # Full symmetry reflection
                equiv.add((i1 + height - 1 - (r - i1), j1 + width - 1 - (c - j1)))

                # All equivalent positions must have same character
                if not all(matrix[pr][pc] == matrix[r][c] for pr, pc in equiv):
