        idx = i + 1
        edges.append((x, y, w, idx))
        adj[x].append((y, idx))
        adj[y].append((x, idx))

    def can_reach(start, target, adj):
        if start == target:
            return True
        queue = [start]
        visited = [False] * (n + 1)
        visited[start] = True
        head = 0
        while head < len(queue):
            u = queue[head]
            head += 1
            if u == target:
                return True
            for v, edge_idx in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    queue.append(v)
        return False

    if not can_reach(s, t, adj):
        return '0\n0\n'

    best_cost = float('inf')
    best_edges = None

    # Try removing one edge
    for i in range(m):
        u, v, w, idx = edges[i]

        found = False
        if (v, idx) in adj[u]:
            adj[u].remove((v, idx))
            found = True
        if found:
            if (u, idx) not in adj[v]:
                adj[v].remove((u, idx))

        if found and not can_reach(s, t, adj):
            if w < best_cost:
                best_cost = w
                best_edges = [idx]

        # Restore edge
        adj[u].append((v, idx))
        adj[v].append((u, idx))

    # Try removing two edges
    for i in range(m):
        u, v, w1, idx1 = edges[i]

