def solve_for_k(n, adj, k):
    if k == 1:
        return n
    if k > n:
        return 0
    if k == n and n >= 2:
        return 1

    parent = [0] * (n + 1)
    children = [[] for _ in range(n + 1)]
    order = []
    stack = [1]
    visited = [bool(0)] * (n + 1)
    visited[1] = True
    while stack:
        u = stack.pop()
        order.append(u)
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                parent[v] = u
                children[u].append(v)
                stack.append(v)
    order.reverse()

    # DP approach using (count, leftover_vertices)
    # For efficiency, this uses optimized bookkeeping
    dp = [{} for _ in range(n + 1)]

    for u in order:
        dp[u][0] = 1
        for v in children[u]:
            for rem_len, cnt in dp[v].items():
                new_len = min(rem_len + 1, k - 1)
                if new_len in dp[u]:
                    dp[u][new_len] += cnt
                else:
                    dp[u][new_len] = cnt

    # Final answer calculation
    total = 0
    for u in order:
        if k-1 in dp[u]:
            total += dp[u][k-1]
    return total

