                # Check if i prefers j over current partner
                cost_ij = cost[i][j]
                cost_ip = cost[i][partner_i - 1] if partner_i > 0 else float('inf')

                # Check if j prefers i over current partner
                cost_ji = cost[j][i]
                cost_jp = cost[j][partner_j - 1] if partner_j > 0 else float('inf')

                if cost_ij < cost_ip and cost_ji < cost_jp:
