def solution(data: str) -> str:
    import sys
    sys.setrecursionlimit(300000)
    from io import StringIO

    input_data = StringIO(data)

    first_line = input_data.readline().strip()
    n, m = map(int, first_line.split())

    edges = []
    for i in range(m):
        line = input_data.readline().strip()
        parts = line.split()
        a, b, e = int(parts[0]), int(parts[1]), int(parts[2])
        edges.append((a, b, e, i))

    # Kruskal's algorithm to build MST
    parent = list(range(n + 1))
    rank = [0] * (n + 1)

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px == py:
            return False
        if rank[px] < rank[py]:
            px, py = py, px
        parent[py] = px
        if rank[px] == rank[py]:
            rank[px] += 1
        return True

    mst_adj = [[] for _ in range(n + 1)]
    mst_indices = set()

    sorted_edges = sorted(edges, key=lambda x: x[2])

    for a, b, e, idx in sorted_edges:
        if union(a, b):
            mst_adj[a].append((b, e))
            mst_adj[b].append((a, e))
            mst_indices.add(idx)

    # Build binary lifting for max edge weight on path
    MAX_LOG = 20
    up = [[0] * MAX_LOG for _ in range(n + 1)]
    max_w = [[0] * MAX_LOG for _ in range(n + 1)]
    depth = [0] * (n + 1)

    root = 1
    depth[root] = 1
    for i in range(MAX_LOG):
        up[root][i] = root
        max_w[root][i] = 0

    stack = [root]
    while stack:
        u = stack.pop()
        for v, w in mst_adj[u]:
            if v != up[u][0]:
                depth[v] = depth[u] + 1
                up[v][0] = u
                max_w[v][0] = w
                stack.append(v)

    for i in range(1, MAX_LOG):
        for j in range(1, n + 1):
            up[j][i] = up[up[j][i-1]][i-1]
            max_w[j][i] = max(max_w[j][i-1], max_w[up[j][i-1]][i-1])

    def get_max_on_path(u, v):
        if u == v:
            return 0

        if depth[u] < depth[v]:
            u, v = v, u

        ans = 0
        for i in range(MAX_LOG - 1, -1, -1):
            if depth[u] - (1 << i) >= depth[v]:
                ans = max(ans, max_w[u][i])
                u = up[u][i]

        if u == v:
            return ans

        for i in range(MAX_LOG - 1, -1, -1):
            if up[u][i] != up[v][i]:
                ans = max(ans, max_w[u][i])
                ans = max(ans, max_w[v][i])
                u = up[u][i]
                v = up[v][i]

        ans = max(ans, max_w[u][0])
        ans = max(ans, max_w[v][0])
        return ans

    # Output E_max for non-MST edges
    results = []
    for a, b, e, idx in edges:
        if idx not in mst_indices:
            results.append(str(get_max_on_path(a, b)))

    return '\n'.join(results)

