def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return ""

    n = int(lines[0])

    queries = []
    for i in range(n):
        parts = list(map(int, lines[i+1].split()))
        queries.append(parts)

    # Store pairs by their original query number (1-indexed)
    query_pair = {}
    for i in range(n):
        if queries[i][0] == 1:
            idx = i + 1  # 1-indexed
            query_pair[idx] = (queries[i][1], queries[i][2])

    active_pairs = set()
    results = []

    for i in range(n):
        t = queries[i][0]

        if t == 1:
            # Add a pair (a, b)
            a, b = queries[i][1], queries[i][2]
            active_pairs.add((a, b))
        elif t == 2:
            # Remove a pair from query number i
            target_query_idx = queries[i][1]
            if target_query_idx in query_pair:
                pair_to_remove = query_pair[target_query_idx]
                if pair_to_remove in active_pairs:
                    active_pairs.remove(pair_to_remove)
        elif t == 3:
            # Query for max(a*q + b)
            q = queries[i][1]
            if not active_pairs:
                results.append("EMPTY SET")
            else:
                max_val = -float('inf')
                for a, b in active_pairs:
                    val = a * q + b
                    if val > max_val:
                        max_val = val
                results.append(str(max_val))

    return '\n'.join(results)


