def solution(input_str):
    import sys
    sys.setrecursionlimit(5000)

    n, k, m = map(int, input_str.strip().split())

    MOD = 10**9 + 7
    fact = [1] * (k + 1)
    for i in range(2, k + 1):
        fact[i] = (fact[i-1] * i) % MOD

    # dp[pos][visited_mask] stores ways to complete from pos and mask
    dp = {}

    def count_ways(pos, length, visited_mask):
        if length == k:
            return 1

        state = (pos, visited_mask)
        if state in dp:
            return dp[state]

        count = 0
        for dest in range(pos, min(pos + m, n) + 1):
            bit = 1 << (dest - 1)
            if not (visited_mask & bit):
                new_mask = visited_mask | bit
                right = (pos + (pos + m - dest) if m > 0 else -1)  # placeholder
                sub = count_ways(dest, length + 1, new_mask)
                if sub > 0:
                    count = (count + sub) % MOD

        dp[state] = count
        return count

    total = 0
    for start in range(1, n + 1):
        bit = 1 << (start - 1)
        sub = count_ways(start, 1, bit)
        total = (total + sub) % MOD

    # Complete result
    answer = total * fact[k - 1] if k > 1 else total
    return str(answer)

def solution(input_str):
    import sys
    from math import sqrt

    lines = input_str.strip().split('\n')
    if not lines:
        return ""

    q = int(lines[0])
    results = []

    def length_of_block(n):
        """Returns total digits in concatenation "123...n" """
        if n <= 0:
            return 0
        total = 0
        start = 1
        d = 1
        while start <= n:
            end = min(n, 10**d - 1)
            count = end - start + 1
            total += count * d
            start *= 10
            d += 1
        return total

    def cumulative(n):
        """Returns sum of length_of_block(1..n) """
        if n <= 0:
            return 0
        if n <= 9:
            return n * (n + 1) // 2
        if n <= 99:
            return 45 + (n + 10) * (n - 9) - 9 * 90
        if n <= 999:
            return 45 + 90 * (n + 10) // 2 * 2 - 810 + (n + 100) * (n - 99) * 3 + 1350 // 2
        if n <= 9999:
            return 24345 + (n + 1000) * (n - 999) * 4 + 405 + 13500 // 2

        return solve_large(n)

    def solve_large(n):
        """Omega(2*d) time where d is number of digits in n"""
        total = 0
        limit = 10**9

        for d in range(1, 18):
            start = 10**(d-1)
            end = min(n, 10**d - 1)
            if start - 1 >= 0:
                if start > limit:
                    current = solve_n(n, limit)
                    return total + current
                for j in range(start, end + 1):
                    block_len = length_of_block(j)
                    total += block_len
        return total

    def length_of_number(i):
        return len(str(i))

    def solve_n(n, limit):
        total = 0
        start = 1
        d = 1
        while start <= n:
            end = min(n, 10**d - 1)
            if start <= limit:
                count = min(end, limit) - start + 1
                total += count * d
            start *= 10
            d += 1
        return total

    def find_digit(k):
        low = 1
        high = 10**9
        block = low

        while low <= high:
            mid = (low + high) // 2
            if cumulative(mid) >= k:
                block = mid
                high = mid - 1
            else:
                low = mid + 1

        prev = cumulative(block - 1)
        pos_in_block = k - prev

        if block <= 9:
            return str(pos_in_block)[0]

        numbers = 1
        remaining = pos_in_block

        d = 1
        start = 1
        while start <= block:
            end = min(block, 10**d - 1)
            count = end - start + 1

            if count * d <= remaining:
                remaining -= count * d
                numbers = end
            else:
                digitize_idx = remaining - 1
                target_num = start + (digitize_idx - 1) // d
                return str(target_num)[digitize_idx % d]

            d += 1
            start *= 10

        return str(numbers)[pos_in_block - 1]

    for i in range(1, q + 1):
        k = int(lines[i])
        result = find_digit(k)
        results.append(str(result))

    return '\n'.join(results)

