def solution(input_str):
    lines = input_str.strip().split('\n')

    if not lines:
        return "-1\n"

    n = int(lines[0])

    # Parse adjacency matrix (n x n)
    adj = []
    for i in range(n):
        row = lines[1 + i]
        adj.append([int(c) for c in row])

    # Parse target counts
    targets = list(map(int, lines[n + 1].split()))

    found_mask = None

    def dfs(index, mask, counts):
        nonlocal found_mask
        if found_mask is not None:
            return

        if index == n:
            # Check if this subset defeats Igor
            for j in range(n):
                if counts[j] == targets[j]:
                    found_mask = None
                    return  # Invalid
            found_mask = mask
            return

        # Option 1: Include employee index in party
        new_counts = list(counts)
        for j in range(n):
            if adj[index][j] == 1:
                new_counts[j] += 1
        dfs(index + 1, mask | (1 << index), new_counts)

        if found_mask is not None:
            return

        # Option 2: Don't include employee index in party
        dfs(index + 1, mask, counts)

    dfs(0, 0, [0] * n)

    if found_mask is None:
        return "-1\n"

    # Convert mask to list of employee numbers (1-indexed)
    selected = []
    for i in range(n):
        if (found_mask >> i) & 1:
            selected.append(i + 1)

    if not selected:
        return "0\n"

    return f"{len(selected)}\n{' '.join(map(str, selected))}\n"

