        attempts.append((parts[0], int(parts[1])))

    def dfs(idx, matches):
        if idx == n:
            return 1 if all(matches[i] == attempts[i][1] for i in range(m)) else 0

        # Precompute which constraints are still "compatible"
        # matches[i] = current number of matches with attempt i

