                    new_matches[i] += 1 if bit == attempts[i][0][0] else new_matches[i]
                else:
                    new_matches[i] = matches[i] + 1 if bit == attempts[i][0][idx] else matches[i]
                count += dfs(idx + 1, tuple(new_matches))
        return count

    # Since straightforward backtracking might be slow, let's try a better approach
    # Use meet-in-the-middle for n up to 35

    half = n // 2
    left_size = half
    right_size = n - half

    left_results = {}  # key: tuple of match counts, value: count
    right_results = {}  # key: tuple of match counts, value: count

    # Enumerate all left halves (2^18 max ~ 262k)
    for mask in range(1 << left_size):
        ini_counts = [0] * m
        remaining_needed = [attempts[i][1] for i in range(m)]
        for i in range(m):
            at = list(attempts[i][0])
            code_l = bin(mask)[2:].zfill(left_size)
            for j in range(left_size):
                if code_l[j] == '1' and at[j] == '1':
                    ini_counts[i] += 1

        left_results[tuple(ini_counts)] = left_results.get(tuple(ini_counts), 0) + 1

        # Enumerate all valid right halves
    for mask in range(1 << right_size):
        ini_counts = [0] * m
        code_r = bin(mask)[2:].zfill(right_size)
        for i in range(m):
            at = list(attempts[i][1])
            for j in range(right_size):
                if code_r[j] == '1' and attempts[i][0][half+j] == '1':
                    ini_counts[i] += 1

        right_results[tuple(ini_counts)] = right_results.get(tuple(ini_counts), 0) + 1

    total = 0

    for k_left, v_left in left_results.items():
        for k_right, v_right in right_results.items():
            if all(v_left[k] + v_right[k] == attempts[k][1] for k in range(m)):
                total += v_left[k_left] * v_right[k_right]

    return str(total)

