                        if val not in blocks:
                            blocks.add(val)

            # Check if all blocks are equal (simplified check)
            # More accurately: check all blocks match block(0,0)
            if len(matrix) == 0:
                continue

            block_base = set()
            for r_idx in range(0, n, r):
                for c_idx in range(0, m, c):
                    block_base.add(matrix[r_idx][c_idx])

            if len(block_base) == 1:
                valid_pairs.append((r, c))
                result += 1

