def solution(graph_input):
    lines = graph_input.strip().split('\n')
    if not lines:
        return "No solution\n"

    n, m = map(int, lines[0].split())

    if m % 2 != 0:
        return "No solution\n"

    if m == 0:
        return "\n"

    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    edge_to_index = {}

    for i in range(m):
        u, v = map(int, lines[1 + i].split())
        adj[u].append(v)
        adj[v].append(u)
        # Store edges in both directions for easy lookup
        key = (min(u, v), max(u, v))
        edge_to_index[key] = i

    result = []
    edges_used = set()

    # Process each vertex to find paths
    for u in range(1, n + 1):
        # Get all unused edges incident to u
        unused_edges = []
        for v in adj[u]:
            key = (min(u, v), max(u, v))
            idx = edge_to_index[key]
            if key not in edges_used:
                unused_edges.append((v, idx, key))

        # Try to pair up edges at vertex u
        i = 0
        while i < len(unused_edges):
            v1, idx1, key1 = unused_edges[i]
            if i + 1 < len(unused_edges):
                v2, idx2, key2 = unused_edges[i + 1]

                # Check if both edges are unused and adjacent at u
                if key1 not in edges_used and key2 not in edges_used:
                    # Create path u -> v1 and then u -> v2
                    result.append((u, v1, v2))
                    edges_used.add(key1)
                    edges_used.add(key2)
                    i += 2
                else:
                    i += 1
            else:
                i += 1

    # Check if all edges were used
    if len(edges_used) != m:
        return "No solution\n"

    # Format output
    output_lines = [f"{p[0]} {p[1]} {p[2]}" for p in result]
    return '\n'.join(output_lines) + '\n'


