def solution(s):
    lines = s.strip().split('\n')
    n = int(lines[0])
    coords = []
    for i in range(n):
        line = lines[1+i].split()
        coords.append((int(line[0]), int(line[1])))

    if n < 3:
        return "0\n"

    MOD = 1000000007

    def cross_product(o, a, b):
        """Returns cross product (a-o) x (b-o)"""
        return (a[0]-o[0])*(b[1]-o[1]) - (a[1]-o[1])*(b[0]-o[0])

    def is_valid_diag(i, j):
        """Check if diagonal (i,j) is valid (doesn't intersect any polygon edge)"""
        for k in range(n):
            k2 = (k + 1) % n
            # Skip if diagonal shares endpoint with edge
            if k == i or k2 == i or k == j or k2 == j:
                continue
            # Check intersection between diagonal (i,j) and edge (k,k2)
            cp1 = cross_product(coords[i], coords[j], coords[k])
            cp2 = cross_product(coords[i], coords[j], coords[k2])
            cp3 = cross_product(coords[k], coords[k2], coords[i])
            cp4 = cross_product(coords[k], coords[k2], coords[j])

            # Check for proper intersection (not at endpoints, crossing lines)
            if (cp1 > 0 and cp2 < 0) or (cp1 < 0 and cp2 > 0):
                if (cp3 > 0 and cp4 < 0) or (cp3 < 0 and cp4 > 0):
                    return False
        return True

    def is_triangle_inside(i, j, k):
        """Check if triangle (i,j,k) is inside the polygon"""
        cp1 = cross_product(coords[i], coords[j], coords[k])
        cp2 = cross_product(coords[j], coords[k], coords[i])
        cp3 = cross_product(coords[k], coords[i], coords[j])

        # If any cross product is 0, points are collinear (degenerate triangle)
        if cp1 == 0 or cp2 == 0 or cp3 == 0:
            return False

        # All cross products must have same sign (all clockwise or all counter-clockwise)
        return (cp1 > 0 and cp2 > 0 and cp3 > 0) or (cp1 < 0 and cp2 < 0 and cp3 < 0)

    # dp[i][j] = number of ways to triangulate subpolygon with vertices i, i+1, ..., j
    dp = [[0] * n for _ in range(n)]

    # Base case: single edge (2 vertices) has 1 way (no triangulation needed)
    for i in range(n):
        dp[i][(i + 1) % n] = 1

    # Fill DP table for subpolygons of increasing size (number of vertices)
    for length in range(3, n + 1):
        for i in range(n):
            j = (i + length) % n

            # Try all possible middle vertices k
            # k forms triangle (i, j, k)
            for k in range(i + 1, j):
                if is_valid_diag(i, k) and is_valid_diag(k, j) and is_triangle_inside(i, j, k):
                    dp[i][j] = (dp[i][j] + dp[i][k] * dp[k][j]) % MOD

    # The answer is the number of ways to triangulate the full polygon
    # dp[0][1] for a polygon with n vertices represents triangulation count
    return str(dp[0][(0 + 1) % n]) + '\n'

