    p = list(map(int, lines[1].split()))

    num_to_idx = {p[i]: i for i in range(n)}

    # Build implication graph for 2-SAT
    # Node 2*i represents "p[i] is NOT in A" (i.e., p[i] is in B)
    # Node 2*i+1 represents "p[i] is in A"

    adj = [[] for _ in range(2 * n)]

    for i in range(n):
        # Constraint: p[i] in A => a-p[i] in A (if a-p[i] exists)
        if a - p[i] in num_to_idx:
            j = num_to_idx[a - p[i]]
            # 2*i+1 (p[i] in A) => 2*j+1 (p[j] in A)
            adj[2 * i + 1].append(2 * j + 1)

        # Constraint: p[i] in B => b-p[i] in B (if b-p[i] exists)
        if b - p[i] in num_to_idx:
            k = num_to_idx[b - p[i]]
            # 2*i (p[i] in B) => 2*k (p[k] in B)
            adj[2 * i].append(2 * k)

    # Tarjan's algorithm for strongly connected components
    dfn = [0] * (2 * n)
    low = [0] * (2 * n)
    stack = []
    on_stack = [False] * (2 * n)
    scc_id = [-1] * (2 * n)
    scc_cnt = [0]

    def tarjan(v):
        dfn[v] = low[v] = scc_cnt[0]
        scc_cnt[0] += 1
        stack.append(v)
        on_stack[v] = True

        for u in adj[v]:
            if dfn[u] == 0:
                tarjan(u)
                low[v] = min(low[v], low[u])
            elif on_stack[u]:
                low[v] = min(low[v], dfn[u])

        if dfn[v] == low[v]:
            while stack:
                u = stack.pop()
                on_stack[u] = False
                scc_id[u] = scc_cnt[0] - 1
                scc_cnt[0] += 1
                if u == v:
                    break

    for i in range(2 * n):
        if dfn[i] == 0:
            tarjan(i)

    ans = [0] * n
    possible = True

    for i in range(n):
        # Check if p[i] in A and p[i] in B are in same SCC
        # This would be a contradiction
        if scc_id[2 * i] == scc_id[2 * i + 1]:
            possible = False
            break

    if not possible:
        return "NO"

    for i in range(n):
        # If scc_id[p[i]_in_A] > scc_id[p[i]_in_B], then p[i] in A
        if scc_id[2 * i + 1] >= scc_id[2 * i]:
            ans[i] = 0
        else:
            ans[i] = 1

    valid = True
    for i in range(n):
        if ans[i] == 0:  # In A
            if a - p[i] in num_to_idx:
