from collections import Counter
from itertools import permutations

def solution(s):
    lines = s.strip().split('\n')
    shuffled = lines[0]
    substring = lines[1] if len(lines) > 1 else ""

    total_chars = len(shuffled)
    available = Counter(shuffled)

    best_n = None

    # k is a number (number of digits in n with value k)
    # n has exactly k digits
    # Total shuffled length = k (number of digits) + digits of k

    # Try all possible values of r (number of digits in k)
    for r in range(1, total_chars):
        digits_left = total_chars - r  # This is the number of digits in n
        k_val = digits_left

        # Check if k_val has exactly r digits
        k_str = str(k_val)
        if len(k_str) != r:
            continue

        # Check if we can form k from available digits
        k_counter = Counter(k_str)
        possible = True
        for c, count in k_counter.items():
            if available[c] < count:
                possible = False
                break

        if not possible:
            continue

        # Form k and get remaining digits for n
        remaining_digits = available.copy()
        for c, count in k_counter.items():
            remaining_digits[c] -= count

        # Build smallest n with the substring
        # n has k digits = digits_left
        n_len = digits_left
        n_available = remaining_digits

        # We need to construct n of length n_len containing substring
        sub_len = len(substring)
        sub_counter = Counter(substring)

        # Check if we can form the substring
        can_form_substring = True
        for c, count in sub_counter.items():
            if n_available[c] < count:
                can_form_substring = False
                break

        if not can_form_substring:
            continue

        # Try all positions for the substring
        best_for_this_k = None

        for start_pos in range(n_len - sub_len + 1):
            before_len = start_pos
            after_len = n_len - sub_len - start_pos

            # Try to build prefix
            if before_len == 0:
                prefix = ""
                prefix_valid = True
            else:
                # Try smallest digits for prefix
                prefix = build_prefix(n_available, before_len)
                prefix_valid = (prefix is not None and len(prefix) == before_len)

            if prefix_valid:
                # Try to build suffix
                if after_len == 0:
                    suffix = ""
                    suffix_valid = True
                else:
                    suffix = build_suffix(n_available, after_len)
                    suffix_valid = (suffix is not None and len(suffix) == after_len)

                if suffix_valid:
                    candidate = prefix + substring + suffix
                    if len(candidate) == n_len:
                        for c in sub_counter:
                            n_available[c] -= sub_counter[c]

                    if best_for_this_k is None or (candidate < best_for_this_k):
                        best_for_this_k = candidate
                        n_available = remaining_digits.copy()

        if best_for_this_k is not None:
            if best_n is None or best_for_this_k < best_n:
                best_n = best_for_this_k

    return best_n if best_n else "0"


def build_prefix(available, length):
    """Build smallest prefix of length with no leading zero unless it's just '0'"""
    result = []

    if length == 0:
        return ""

    # Find smallest non-zero digit for first position
    for c in '123456789':
        if available[c] > 0:
            result.append(c)
            available[c] -= 1
            break
    else:
        # No non-zero available, can only form "0" if length=1
        if length == 1 and '0' in available and available['0'] > 0:
            result.append('0')
        return None

    # Fill rest with smallest digits
    for i in range(1, length):
        for c in '0123456789':
            if c not in available or available[c] <= 0:
                continue
            result.append(c)
            available[c] -= 1
            break

    return ''.join(result)


def build_suffix(available, length):
    """Build smallest suffix of given length using smallest digits"""
    result = []

    digits_left = length

    # Fill with smallest available digits
    for c in '0123456789':
        if c not in available or available[c] <= 0:
            continue
        for _ in range(min(available[c], itertools.count())):
            if digits_left > 0:
                result.append(c)
                digits_left -= 1
                available[c] -= 1
                if digits_left == 0:
                    break
        if digits_left == 0:
            break

    return ''.join(result) if len(result) == length else None

