        # Try adding remaining points one at a time
        for i in range(idx, len(valid_points)):
            selected.append(valid_points[i])
            backtrack(i + 1, selected)
            selected.pop()

    backtrack(0, [])

    # Format output
    output = [str(best_score)]
    for point in best_config:
        output.append(f"{point[0]} {point[1]}")

    return '\n'.join(output)

# Comprehensive solution for the grammar problem

MOD = 10**9 + 7

class Result:
    def __init__(self, value, length):
        self.value = value
        self.length = length

def parse_range(l_str, r_str):
    l = int(l_str)
    r = int(r_str)

    if l == r:
        return Result(int(l) % MOD, len(l_str))

    value = int(l) % MOD
    length = len(l_str)

    for i in range(l + 1, r + 1):
        s = str(i)
        value = (value * pow(10, len(s), MOD) + int(s)) % MOD
        length += len(s)

    return Result(value, length)

def parse_number(s, pos):
    end = pos
    while end < len(s) and s[end].isdigit():
        end += 1
    num_str = s[pos:end]
    return num_str, end

def compute_repeat(n_str, expr_value, expr_length):
    n = int(n_str)
    if n == 0:
        return Result(0, 0)

    L = expr_length
    total_len = L * n

    if n <= 100000:
        val = 0
        base = expr_value.value
        shift = pow(10, L, MOD)
        for _ in range(n):
            val = (val * shift + base) % MOD
        return Result(val, total_len)
    else:
        shift = pow(10, L, MOD)
        if shift == 0:
            return Result(0, total_len)
        numerator = (pow(10, L * n, MOD) - 1)
        denom = (shift - 1)
        total_val = (numerator * pow(denom, MOD - 2, MOD)) % MOD * expr_value.value % MOD
        return Result(total_val, total_len % (MOD - 1))

def parse_term(s, pos):
    num_str, pos = parse_number(s, pos)
    n = int(num_str)

    if pos < len(s) and s[pos] == '-':
        pos += 1
        r_str, pos = parse_number(s, pos)
        return parse_range(num_str, r_str), pos
    elif pos < len(s) and s[pos] == '(':
        pos += 1
        expr_val, expr_len = parse_expr(s, pos)
        if pos < len(s) and s[pos] == ')':
            pos += 1
        return compute_repeat(num_str, expr_val, expr_len), pos
    else:
        return Result(int(num_str) % MOD, len(num_str)), pos

def parse_expr(s, pos):
    left, pos = parse_term(s, pos)

    while pos < len(s) and s[pos] == '+':
        pos += 1
        right, pos = parse_term(s, pos)
        left = concat(left, right)

    return left, pos

def concat(a, b):
    if a is None or a.value == 0 and a.length == 0:
        return b
    if b is None or b.value == 0 and b.length == 0:
        return a

    MOD = 10**9 + 7
    return Result((a.value * pow(10, b.length, MOD) + b.value) % MOD, a.length + b.length)

def solution(s):
    s = s.strip()
    if not s:
        return "0\n"

    result, _ = parse_expr(s, 0)
    return f"{result.value}\n"

def solution(n):
    n = int(n)
    memo = {}

    def get_digits(num):
        return set(int(d) for d in str(num))

    def bfs(n):
        from collections import deque

        queue = deque([(n, 0)])  # (current number, steps)
        visited = set()
        visited.add(n)

        while queue:
            num, steps = queue.popleft()

            if num == 0:
                return steps

            # Get all digits in num
            digits = set(str(num))

            # Try subtracting each non-zero digit
            for d in digits:
                if int(d) > 0:
                    next_num = num - int(d)
                    if next_num not in visited:
                        visited.add(next_num)
                        queue.append((next_num, steps + 1))

        return -1

    return str(bfs(n))
